-- =====================================================================
-- Grow: initial database schema
-- Run once in Supabase → SQL Editor → New query → paste all → Run.
--
-- Rules
--   • Every row belongs to one user (user_id → auth.users). Deleting the
--     user deletes all their data (on delete cascade).
--   • Row level security: a signed-in user can only read and write their own rows.
--   • Money is stored as bigint paisa (1 taka = 100 paisa), never floats.
--   • IDs are text generated by the app (UUIDs), so rows can be created offline.
-- =====================================================================

-- ---------- profiles: one row per user ----------
create table if not exists public.profiles (
  id            uuid primary key references auth.users (id) on delete cascade,
  display_name  text        not null default '' check (char_length(display_name) <= 100),
  avatar_url    text        not null default '',
  currency      text        not null default 'BDT' check (currency ~ '^[A-Z]{3}$'),
  hide_amounts  boolean     not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- ---------- accounts: where money sits (Cash, bKash, Bank, ...) ----------
create table if not exists public.accounts (
  user_id          uuid   not null default auth.uid() references auth.users (id) on delete cascade,
  id               text   not null check (char_length(id) between 1 and 64),
  name             text   not null check (char_length(name) between 1 and 100),
  opening_balance  bigint not null default 0,
  sort             int    not null default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  primary key (user_id, id)
);

-- ---------- transactions: income, expense, transfer ----------
create table if not exists public.transactions (
  user_id      uuid      not null default auth.uid() references auth.users (id) on delete cascade,
  id           text      not null check (char_length(id) between 1 and 64),
  type         text      not null check (type in ('income', 'expense', 'transfer')),
  occurred_at  timestamp not null,          -- user's local date & time (no time zone)
  account_id   text      not null,
  to_account   text,                        -- only for transfers
  category     text      not null default '' check (char_length(category) <= 100),
  subcategory  text      not null default '' check (char_length(subcategory) <= 100),
  amount       bigint    not null check (amount > 0),
  note         text      not null default '' check (char_length(note) <= 200),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  primary key (user_id, id),
  foreign key (user_id, account_id) references public.accounts (user_id, id) on delete cascade,
  foreign key (user_id, to_account) references public.accounts (user_id, id) on delete cascade,
  check (
    (type = 'transfer' and to_account is not null and to_account <> account_id)
    or (type <> 'transfer' and to_account is null)
  )
);
create index if not exists transactions_by_date on public.transactions (user_id, occurred_at desc);

-- ---------- holdings: investments ----------
create table if not exists public.holdings (
  user_id     uuid   not null default auth.uid() references auth.users (id) on delete cascade,
  id          text   not null check (char_length(id) between 1 and 64),
  name        text   not null check (char_length(name) between 1 and 200),
  type        text   not null check (type in ('Stocks','Mutual funds','Savings certificates','Fixed deposit','Gold','Crypto','Other')),
  invested    bigint not null default 0 check (invested >= 0),
  value       bigint not null default 0 check (value >= 0),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  primary key (user_id, id)
);

-- ---------- budgets: monthly limit per expense category ----------
create table if not exists public.budgets (
  user_id     uuid   not null default auth.uid() references auth.users (id) on delete cascade,
  category    text   not null check (char_length(category) between 1 and 100),
  amount      bigint not null default 0 check (amount >= 0),
  updated_at  timestamptz not null default now(),
  primary key (user_id, category)
);

-- =====================================================================
-- Row level security
-- =====================================================================
alter table public.profiles     enable row level security;
alter table public.accounts     enable row level security;
alter table public.transactions enable row level security;
alter table public.holdings     enable row level security;
alter table public.budgets      enable row level security;

drop policy if exists "own rows" on public.profiles;
create policy "own rows" on public.profiles for all to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

drop policy if exists "own rows" on public.accounts;
create policy "own rows" on public.accounts for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

drop policy if exists "own rows" on public.transactions;
create policy "own rows" on public.transactions for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

drop policy if exists "own rows" on public.holdings;
create policy "own rows" on public.holdings for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

drop policy if exists "own rows" on public.budgets;
create policy "own rows" on public.budgets for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- =====================================================================
-- Triggers
-- =====================================================================

-- keep updated_at current on every edit
create or replace function public.touch_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin new.updated_at = now(); return new; end $$;

do $$ declare t text; begin
  foreach t in array array['profiles','accounts','transactions','holdings','budgets'] loop
    execute format('drop trigger if exists touch on public.%I', t);
    execute format('create trigger touch before update on public.%I for each row execute function public.touch_updated_at()', t);
  end loop;
end $$;

-- new user → profile (name/photo from Google or sign-up form) + three starter accounts
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, display_name, avatar_url)
  values (
    new.id,
    left(coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name', ''), 100),
    coalesce(new.raw_user_meta_data ->> 'avatar_url', new.raw_user_meta_data ->> 'picture', '')
  )
  on conflict (id) do nothing;

  insert into public.accounts (user_id, id, name, sort) values
    (new.id, 'cash',  'Cash',         0),
    (new.id, 'bkash', 'bKash',        1),
    (new.id, 'bank',  'Bank account', 2)
  on conflict do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();
